#include <string>
#include <unordered_set>
#include <algorithm>
using namespace std;

class Solution {
    int backtrack(const string& s, int idx, unordered_set<string>& seen) {
        if (idx == (int)s.size()) return 0;
        int best = -1;
        for (int end = idx + 1; end <= (int)s.size(); ++end) {
            string sub = s.substr(idx, end - idx);
            if (seen.find(sub) == seen.end()) {
                seen.insert(sub);
                int res = backtrack(s, end, seen);
                if (res != -1) {
                    best = max(best, 1 + res);
                }
                seen.erase(sub);
            }
        }
        return best;
    }
public:
    int maxUniqueSplit(string s) {
        unordered_set<string> seen;
        return backtrack(s, 0, seen);
    }
};

import java.util.*;

class Solution {
    private int backtrack(String s, int idx, Set<String> seen) {
        if (idx == s.length()) return 0;
        int best = -1;
        for (int end = idx + 1; end <= s.length(); ++end) {
            String sub = s.substring(idx, end);
            if (!seen.contains(sub)) {
                seen.add(sub);
                int res = backtrack(s, end, seen);
                if (res != -1) {
                    best = Math.max(best, 1 + res);
                }
                seen.remove(sub);
            }
        }
        return best;
    }
    public int maxUniqueSplit(String s) {
        return backtrack(s, 0, new HashSet<>());
    }
}

