var maxUniqueSplit = function(s) {
    const seen = new Set();
    function backtrack(idx) {
        if (idx === s.length) return 0;
        let best = -1;
        for (let end = idx + 1; end <= s.length; ++end) {
            const sub = s.slice(idx, end);
            if (!seen.has(sub)) {
                seen.add(sub);
                const res = backtrack(end);
                if (res !== -1) {
                    best = Math.max(best, 1 + res);
                }
                seen.delete(sub);
            }
        }
        return best;
    }
    return backtrack(0);
};
